<?php
declare(strict_types=1);
namespace MyGame\Infrastructure\Banking;
use PDO;
final class DatabaseLoanRepository {
 public function __construct(private PDO $pdo){}
 public function company(int $id): ?array {$s=$this->pdo->prepare('SELECT * FROM companies WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;}
 public function ensureDemoCompany(): array {$c=$this->company(1);if($c)return $c;$country=(int)$this->pdo->query("SELECT id FROM countries WHERE code='LT' LIMIT 1")->fetchColumn();$s=$this->pdo->prepare('INSERT INTO companies(country_id,name,cash,assets,liabilities,monthly_revenue,monthly_profit,age_months) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$country,'Mano įmonė',25000,40000,5000,18000,3200,18]);return $this->company((int)$this->pdo->lastInsertId());}
 public function accounts(int $companyId): array {$s=$this->pdo->prepare('SELECT a.*,b.name bank_name,b.code bank_code FROM company_bank_accounts a JOIN banks b ON b.id=a.bank_id WHERE a.company_id=? AND a.is_active=1 ORDER BY a.is_primary DESC,a.id');$s->execute([$companyId]);return $s->fetchAll();}
 public function accountAtBank(int $companyId,int $bankId): ?array {$s=$this->pdo->prepare('SELECT a.*,b.name bank_name,b.code bank_code FROM company_bank_accounts a JOIN banks b ON b.id=a.bank_id WHERE a.company_id=? AND a.bank_id=? AND a.is_active=1 LIMIT 1');$s->execute([$companyId,$bankId]);return $s->fetch()?:null;}
 public function openAccount(int $companyId,int $bankId): array {if($a=$this->accountAtBank($companyId,$bankId))return $a;$s=$this->pdo->prepare('SELECT id,code FROM banks WHERE id=? AND is_active=1');$s->execute([$bankId]);$b=$s->fetch();if(!$b)throw new \RuntimeException('Bankas nerastas arba neaktyvus.');$has=(bool)$this->accounts($companyId);$code=strtoupper(substr(preg_replace('/[^A-Za-z0-9]/','',(string)$b['code']),0,2));$number='LT'.str_pad((string)(10+($companyId%89)),2,'0',STR_PAD_LEFT).str_pad($code,2,'0').str_pad((string)$bankId,4,'0',STR_PAD_LEFT).str_pad((string)$companyId,8,'0',STR_PAD_LEFT);$q=$this->pdo->prepare('INSERT INTO company_bank_accounts(company_id,bank_id,account_number,currency,balance,is_primary) VALUES(?,?,?,?,0,?)');$q->execute([$companyId,$bankId,$number,'EUR',$has?0:1]);return $this->accountAtBank($companyId,$bankId);}
 public function setPrimaryAccount(int $companyId,int $accountId): void {$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT id FROM company_bank_accounts WHERE id=? AND company_id=? AND is_active=1');$s->execute([$accountId,$companyId]);if(!$s->fetchColumn())throw new \RuntimeException('Sąskaita nerasta.');$this->pdo->prepare('UPDATE company_bank_accounts SET is_primary=0 WHERE company_id=?')->execute([$companyId]);$this->pdo->prepare('UPDATE company_bank_accounts SET is_primary=1 WHERE id=? AND company_id=?')->execute([$accountId,$companyId]);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
 public function transactions(int $accountId,int $limit=10): array {$s=$this->pdo->prepare('SELECT * FROM bank_account_transactions WHERE account_id=? ORDER BY created_at DESC,id DESC LIMIT '.max(1,min(100,$limit)));$s->execute([$accountId]);return $s->fetchAll();}
 public function banks(): array {$sql="SELECT b.*,p.id product_id,p.name product_name,p.min_amount,p.max_amount,p.max_term_months,p.margin product_margin,p.min_equity_percent FROM banks b JOIN bank_loan_products p ON p.bank_id=b.id AND p.is_active=1 WHERE b.is_active=1 ORDER BY b.id";return $this->pdo->query($sql)->fetchAll();}
 public function policy(): array {$s=$this->pdo->query("SELECT parameter_key,value FROM economic_parameters WHERE section='banking'");$r=[];foreach($s as $p)$r[$p['parameter_key']]=(float)$p['value'];return $r;}
 public function application(int $id,int $companyId): ?array {$s=$this->pdo->prepare("SELECT a.*,b.name bank_name,p.name product_name FROM loan_applications a JOIN banks b ON b.id=a.bank_id LEFT JOIN bank_loan_products p ON p.id=a.loan_product_id WHERE a.id=? AND a.company_id=?");$s->execute([$id,$companyId]);return $s->fetch()?:null;}
 public function activeLoans(int $companyId): array {$s=$this->pdo->prepare("SELECT l.*,b.name bank_name,a.requested_amount FROM company_loans l JOIN banks b ON b.id=l.bank_id JOIN loan_applications a ON a.id=l.application_id WHERE l.company_id=? AND l.status='active' ORDER BY l.started_at DESC");$s->execute([$companyId]);return $s->fetchAll();}
 public function acceptApplication(int $applicationId,int $companyId,float $monthlyPayment): array {$this->pdo->beginTransaction();try{$app=$this->application($applicationId,$companyId);if(!$app||$app['status']!=='approved')throw new \RuntimeException('Šio paskolos pasiūlymo priimti negalima.');$account=$this->accountAtBank($companyId,(int)$app['bank_id']);if(!$account)throw new \RuntimeException('Paskolos banke nėra aktyvios įmonės sąskaitos.');$amount=(float)$app['requested_amount'];$newBalance=(float)$account['balance']+$amount;$this->pdo->prepare('UPDATE company_bank_accounts SET balance=? WHERE id=?')->execute([$newBalance,$account['id']]);$this->pdo->prepare('UPDATE companies SET liabilities=liabilities+? WHERE id=?')->execute([$amount,$companyId]);$this->pdo->prepare("UPDATE loan_applications SET status='accepted' WHERE id=?")->execute([$applicationId]);$s=$this->pdo->prepare("INSERT INTO company_loans(application_id,company_id,bank_id,principal,outstanding_principal,annual_interest_rate,term_months,monthly_payment,started_at,next_payment_at,status) VALUES(?,?,?,?,?,?,?,?,(SELECT game_date FROM game_clock WHERE id=1),DATE_ADD((SELECT game_date FROM game_clock WHERE id=1),INTERVAL 1 MONTH),'active')");$s->execute([$applicationId,$companyId,$app['bank_id'],$amount,$amount,$app['offered_interest_rate'],$app['requested_term_months'],$monthlyPayment]);$loanId=(int)$this->pdo->lastInsertId();$remaining=$amount;$monthlyRate=((float)$app['offered_interest_rate']/100)/12;for($i=1;$i<=(int)$app['requested_term_months'];$i++){$interest=round($remaining*$monthlyRate,2);$principal=$i===(int)$app['requested_term_months']?$remaining:round($monthlyPayment-$interest,2);$principal=max(0,min($remaining,$principal));$scheduled=round($principal+$interest,2);$gameDate=(string)$this->pdo->query('SELECT game_date FROM game_clock WHERE id=1')->fetchColumn();$due=(new \DateTimeImmutable($gameDate))->modify('+'.$i.' month')->format('Y-m-d H:i:s');$q=$this->pdo->prepare("INSERT INTO loan_payments(loan_id,installment_no,due_at,scheduled_amount,interest_amount,principal_amount,status) VALUES(?,?,?,?,?,?,'waiting')");$q->execute([$loanId,$i,$due,$scheduled,$interest,$principal]);$remaining=max(0,$remaining-$principal);}$t=$this->pdo->prepare("INSERT INTO bank_account_transactions(account_id,transaction_type,amount,balance_after,reference_type,reference_id,description) VALUES(?,?,?,?,?,?,?)");$t->execute([$account['id'],'loan_disbursement',$amount,$newBalance,'loan',$loanId,'Verslo paskolos išmokėjimas · '.$app['bank_name']]);$this->pdo->commit();return ['loan_id'=>$loanId,'account_id'=>(int)$account['id'],'balance'=>$newBalance];}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
 public function paymentSchedule(int $loanId): array {$s=$this->pdo->prepare("SELECT *,GREATEST(0,DATEDIFF((SELECT game_date FROM game_clock WHERE id=1),due_at)) late_days FROM loan_payments WHERE loan_id=? ORDER BY installment_no");$s->execute([$loanId]);return $s->fetchAll();}
 public function refreshLoanPayments(int $companyId): void {$s=$this->pdo->prepare("SELECT lp.*,l.company_id FROM loan_payments lp JOIN company_loans l ON l.id=lp.loan_id WHERE l.company_id=? AND l.status='active' AND lp.paid_at IS NULL");$s->execute([$companyId]);foreach($s as $p){$gameDate=(string)$this->pdo->query('SELECT game_date FROM game_clock WHERE id=1')->fetchColumn();$days=max(0,(int)((new \DateTimeImmutable(substr((string)$p['due_at'],0,10)))->diff(new \DateTimeImmutable($gameDate))->format('%r%a')));$penalty=$days>=2?round((float)$p['scheduled_amount']*.0005*($days-1),2):0;$status=$days<=0?'waiting':($days===1?'due':'late');$q=$this->pdo->prepare('UPDATE loan_payments SET penalty_amount=?,status=? WHERE id=?');$q->execute([$penalty,$status,$p['id']]);}}
 public function migrateActiveLoanDatesToGameClock(int $companyId):void{$game=(string)$this->pdo->query('SELECT game_date FROM game_clock WHERE id=1')->fetchColumn();$s=$this->pdo->prepare("SELECT l.id,MIN(p.due_at) first_due FROM company_loans l JOIN loan_payments p ON p.loan_id=l.id AND p.paid_at IS NULL WHERE l.company_id=? AND l.status='active' GROUP BY l.id");$s->execute([$companyId]);foreach($s as $x){$first=substr((string)$x['first_due'],0,10);if($first>$game){$days=(int)floor((strtotime($first)-strtotime($game))/86400);if($days>120){$start=(new \DateTimeImmutable($game))->modify('-1 month');$ps=$this->pdo->prepare("SELECT id,installment_no FROM loan_payments WHERE loan_id=? AND paid_at IS NULL ORDER BY installment_no");$ps->execute([$x['id']]);foreach($ps as $p){$due=$start->modify('+'.(int)$p['installment_no'].' month')->format('Y-m-d H:i:s');$this->pdo->prepare('UPDATE loan_payments SET due_at=? WHERE id=?')->execute([$due,$p['id']]);}$next=$this->pdo->prepare("SELECT due_at FROM loan_payments WHERE loan_id=? AND paid_at IS NULL ORDER BY installment_no LIMIT 1");$next->execute([$x['id']]);$this->pdo->prepare('UPDATE company_loans SET started_at=?,next_payment_at=? WHERE id=?')->execute([$start->format('Y-m-d H:i:s'),$next->fetchColumn(),$x['id']]);}}}}
 public function payInstallment(int $companyId,int $paymentId): void {$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT p.*,l.bank_id,l.company_id,l.outstanding_principal,b.name bank_name FROM loan_payments p JOIN company_loans l ON l.id=p.loan_id JOIN banks b ON b.id=l.bank_id WHERE p.id=? AND l.company_id=? FOR UPDATE");$s->execute([$paymentId,$companyId]);$p=$s->fetch();if(!$p||$p['paid_at'])throw new \RuntimeException('Įmoka nerasta arba jau sumokėta.');$account=$this->accountAtBank($companyId,(int)$p['bank_id']);if(!$account)throw new \RuntimeException('Nėra aktyvios sąskaitos paskolos banke.');$total=(float)$p['scheduled_amount']+(float)$p['penalty_amount'];if((float)$account['balance']<$total)throw new \RuntimeException('Sąskaitoje nepakanka lėšų įmokai.');$balance=(float)$account['balance']-$total;$this->pdo->prepare('UPDATE company_bank_accounts SET balance=? WHERE id=?')->execute([$balance,$account['id']]);$this->pdo->prepare("UPDATE loan_payments SET paid_amount=?,paid_at=(SELECT game_date FROM game_clock WHERE id=1),status='paid' WHERE id=?")->execute([$total,$paymentId]);$principal=min((float)$p['principal_amount'],(float)$p['outstanding_principal']);$this->pdo->prepare('UPDATE company_loans SET outstanding_principal=GREATEST(0,outstanding_principal-?) WHERE id=?')->execute([$principal,$p['loan_id']]);$this->pdo->prepare('UPDATE companies SET liabilities=GREATEST(0,liabilities-?) WHERE id=?')->execute([$principal,$companyId]);$t=$this->pdo->prepare("INSERT INTO bank_account_transactions(account_id,transaction_type,amount,balance_after,reference_type,reference_id,description) VALUES(?,?,?,?,?,?,?)");$t->execute([$account['id'],'loan_payment',-$total,$balance,'loan_payment',$paymentId,'Paskolos įmoka · '.$p['bank_name']]);$left=(float)$p['outstanding_principal']-$principal;if($left<=0.01)$this->pdo->prepare("UPDATE company_loans SET status='paid' WHERE id=?")->execute([$p['loan_id']]);else{$n=$this->pdo->prepare("SELECT due_at FROM loan_payments WHERE loan_id=? AND paid_at IS NULL AND id<>? ORDER BY installment_no LIMIT 1");$n->execute([$p['loan_id'],$paymentId]);$next=$n->fetchColumn();if($next)$this->pdo->prepare('UPDATE company_loans SET next_payment_at=? WHERE id=?')->execute([$next,$p['loan_id']]);}$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
 public function createApplication(int $companyId,array $bank,float $amount,int $months,array $result): int {$status=$result['approved']?'approved':'rejected';$s=$this->pdo->prepare('INSERT INTO loan_applications(company_id,bank_id,loan_product_id,requested_amount,requested_term_months,equity_percent,risk_score,risk_margin,offered_interest_rate,status,decision_reason,decided_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())');$s->execute([$companyId,$bank['id'],$bank['product_id'],$amount,$months,$result['equity_percent'],$result['risk_score'],$result['risk_margin'],$result['interest_rate'],$status,$result['reason']]);return (int)$this->pdo->lastInsertId();}
}
